t.script:
(function() {
'use strict';

/* ========================================================
   DATA from server
   ======================================================== */
const TEMPLATE_ID = ;
const SIGN_ITEM_TYPES = ;
const SIGN_ROLES = ;
const INITIAL_ITEMS = ;

/* ========================================================
   STATE
   ======================================================== */
let signItems = [];   // { _id, id, type_id, type, page, posX, posY, width, height, required, responsible_id, name, placeholder, _dirty }
let nextLocalId = -1; // negative IDs = newly created (not yet saved)
let selectedItemId = null;
let isDirty = false;

// PDF state
let pdfDoc = null;
let pageWrappers = {}; // pageNum → { wrapper, canvas, viewport }

/* ========================================================
   INIT PDF.js
   ======================================================== */
const pdfjsLib = window['pdfjs-dist/build/pdf'];
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

/* ========================================================
   TYPE/ROLE HELPERS
   ======================================================== */
const TYPE_META = {
    signature: { label: 'Signature', icon: '✍', desc: 'Handwritten signature',    cls: 'sfi-signature', ftCls: 'ft-signature', defW: 0.2, defH: 0.07 },
    initial:   { label: 'Initial',   icon: '📝', desc: 'Initials abbreviation',    cls: 'sfi-initial',   ftCls: 'ft-initial',   defW: 0.1, defH: 0.05 },
    text:      { label: 'Text',      icon: '𝐓',  desc: 'Single-line text input',  cls: 'sfi-text',      ftCls: 'ft-text',      defW: 0.2, defH: 0.04 },
    textarea:  { label: 'Text Area', icon: '≡',  desc: 'Multi-line text input',   cls: 'sfi-textarea',  ftCls: 'ft-textarea',  defW: 0.25, defH: 0.1 },
    checkbox:  { label: 'Checkbox',  icon: '☑',  desc: 'Checkbox / tick field',   cls: 'sfi-checkbox',  ftCls: 'ft-checkbox',  defW: 0.05, defH: 0.05 },
};

function getTypeMeta(typeStr) {
    return TYPE_META[typeStr] || TYPE_META['text'];
}

function getRoleById(id) {
    return SIGN_ROLES.find(r => r.id === id) || null;
}

function getOdooColorHex(colorIdx) {
    const palette = [
        '#e74c3c','#e67e22','#f1c40f','#2ecc71','#1abc9c',
        '#3498db','#9b59b6','#e91e63','#795548','#607d8b',
        '#00bcd4','#cddc39'
    ];
    return palette[colorIdx % palette.length] || '#6366f1';
}

/* ========================================================
   BUILD SIDEBAR
   ======================================================== */
function buildFieldCards() {
    const container = document.getElementById('es-field-cards');
    container.innerHTML = '';
    SIGN_ITEM_TYPES.forEach(t => {
        const meta = getTypeMeta(t.item_type);
        const card = document.createElement('div');
        card.className = 'es-field-card ' + meta.ftCls;
        card.draggable = true;
        card.dataset.typeId = t.id;
        card.dataset.itemType = t.item_type;
        card.dataset.typeName = t.name;
        card.innerHTML = `
            <div class="es-field-icon">${meta.icon}</div>
            <div class="es-field-info">
                <div class="es-field-name">${t.name}</div>
                <div class="es-field-desc">${meta.desc}</div>
            </div>
        `;
        card.addEventListener('dragstart', onSidebarDragStart);
        card.addEventListener('dragend', () => card.classList.remove('dragging'));
        container.appendChild(card);
    });
}

/* ========================================================
   BUILD ROLE SELECT
   ======================================================== */
function buildRoleSelect() {
    const sel = document.getElementById('es-prop-role');
    SIGN_ROLES.forEach(r => {
        const opt = document.createElement('option');
        opt.value = r.id;
        opt.textContent = r.name;
        sel.appendChild(opt);
    });
}

/* ========================================================
   SIDEBAR DRAG START
   ======================================================== */
let dragPayload = null; // { typeId, itemType, typeName }

function onSidebarDragStart(e) {
    const card = e.currentTarget;
    dragPayload = {
        typeId: parseInt(card.dataset.typeId),
        itemType: card.dataset.itemType,
        typeName: card.dataset.typeName,
    };
    card.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'copy';
    e.dataTransfer.setData('text/plain', 'es-field');
}

/* ========================================================
   PAGE WRAPPER DROP HANDLERS
   ======================================================== */
function attachPageDropHandlers(wrapper, pageNum) {
    wrapper.addEventListener('dragover', e => {
        if (!dragPayload) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = 'copy';
        wrapper.classList.add('drag-over');
    });
    wrapper.addEventListener('dragleave', e => {
        if (!e.relatedTarget || !wrapper.contains(e.relatedTarget)) {
            wrapper.classList.remove('drag-over');
        }
    });
    wrapper.addEventListener('drop', e => {
        e.preventDefault();
        wrapper.classList.remove('drag-over');
        if (!dragPayload) return;

        const { typeId, itemType, typeName } = dragPayload;
        dragPayload = null;

        const rect = wrapper.getBoundingClientRect();
        const meta = getTypeMeta(itemType);
        const defW = meta.defW;
        const defH = meta.defH;

        // Centre the dropped item on the cursor
        let posX = (e.clientX - rect.left) / rect.width  - defW / 2;
        let posY = (e.clientY - rect.top)  / rect.height - defH / 2;
        posX = Math.max(0, Math.min(1 - defW, posX));
        posY = Math.max(0, Math.min(1 - defH, posY));

        const item = {
            _id: nextLocalId--,
            id: 0,
            type_id: [typeId, typeName],
            type: itemType,
            page: pageNum,
            posX: +posX.toFixed(4),
            posY: +posY.toFixed(4),
            width: defW,
            height: defH,
            required: true,
            responsible_id: false,
            name: '',
            placeholder: '',
        };
        signItems.push(item);
        placeFieldOnPage(item);
        selectItem(item._id);
        markDirty();
        updatePlacedList();
    });
}

/* ========================================================
   RENDER PDF & PLACE EXISTING ITEMS
   ======================================================== */
async function renderPDF(url) {
    const loadingTask = pdfjsLib.getDocument(url);
    pdfDoc = await loadingTask.promise;

    const viewer = document.getElementById('es-viewer');
    document.getElementById('es-loading').remove();

    for (let i = 1; i <= pdfDoc.numPages; i++) {
        const page = await pdfDoc.getPage(i);
        const scale = 1.8;
        const viewport = page.getViewport({ scale });

        // Page label
        const labelEl = document.createElement('div');
        labelEl.className = 'es-page-label';
        labelEl.textContent = `Page ${i} of ${pdfDoc.numPages}`;

        // Wrapper
        const wrapper = document.createElement('div');
        wrapper.className = 'es-page-wrapper';
        wrapper.dataset.page = i;
        wrapper.style.position = 'relative';
        wrapper.style.maxWidth = '900px';
        wrapper.style.width = '100%';

        // Canvas
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        canvas.height = viewport.height;
        canvas.width  = viewport.width;
        canvas.style.display = 'block';
        canvas.style.width = '100%';

        wrapper.appendChild(canvas);
        viewer.appendChild(wrapper);
        viewer.appendChild(labelEl);

        const renderCtx = { canvasContext: ctx, viewport };
        await page.render(renderCtx).promise;

        pageWrappers[i] = { wrapper, canvas, viewport };
        attachPageDropHandlers(wrapper, i);

        // Empty hint
        const hint = document.createElement('div');
        hint.className = 'es-empty-hint';
        hint.id = `page-hint-${i}`;
        hint.innerHTML = `<div class="es-empty-hint-icon">&#8681;</div><div class="es-empty-hint-text">Drag a field here</div>`;
        wrapper.appendChild(hint);
    }

    // Place existing items
    signItems.forEach(item => placeFieldOnPage(item));
    updatePlacedList();
}

/* ========================================================
   PLACE A FIELD OVERLAY ON ITS PAGE
   ======================================================== */
function placeFieldOnPage(item) {
    const pw = pageWrappers[item.page];
    if (!pw) return;

    // Hide empty hint if fields exist on this page
    const hint = document.getElementById(`page-hint-${item.page}`);
    if (hint) hint.style.display = 'none';

    const meta = getTypeMeta(item.type);

    const el = document.createElement('div');
    el.className = `sign-field-item ${meta.cls}`;
    el.id = `sfi-${item._id}`;
    el.style.left   = (item.posX * 100) + '%';
    el.style.top    = (item.posY * 100) + '%';
    el.style.width  = (item.width * 100) + '%';
    el.style.height = (item.height * 100) + '%';

    // Apply role color if set
    applyRoleColorToEl(el, item.responsible_id);

    // Badge
    const badge = document.createElement('div');
    badge.className = 'sign-field-badge';
    badge.textContent = meta.label;
    el.appendChild(badge);

    // Label
    const lbl = document.createElement('div');
    lbl.className = 'sign-field-label';
    lbl.textContent = item.name || meta.icon;
    el.appendChild(lbl);

    // Delete button
    const delBtn = document.createElement('button');
    delBtn.className = 'sign-field-delete';
    delBtn.innerHTML = '&#10005;';
    delBtn.title = 'Delete field';
    delBtn.addEventListener('mousedown', e => { e.stopPropagation(); deleteItem(item._id); });
    el.appendChild(delBtn);

    // Resize handle
    const resizeHandle = document.createElement('div');
    resizeHandle.className = 'sign-field-resize';
    resizeHandle.title = 'Resize';
    resizeHandle.addEventListener('mousedown', e => onResizeStart(e, item._id));
    el.appendChild(resizeHandle);

    // Click → select
    el.addEventListener('mousedown', e => {
        if (e.target === delBtn || e.target === resizeHandle) return;
        onFieldMouseDown(e, item._id);
    });

    pw.wrapper.appendChild(el);
}

/* ========================================================
   APPLY ROLE COLOR
   ======================================================== */
function applyRoleColorToEl(el, roleId) {
    if (!roleId) return;
    const roleIdNum = Array.isArray(roleId) ? roleId[0] : roleId;
    const role = getRoleById(roleIdNum);
    if (!role) return;
    const hex = getOdooColorHex(role.color || 0);
    el.style.borderColor = hex;
    // Remove type class border and apply role color
    el.classList.forEach(cls => {
        if (cls.startsWith('sfi-')) {
            el.style.background = hex + '22'; // translucent
            el.style.color = hex;
        }
    });
}

/* ========================================================
   DRAG TO MOVE
   ======================================================== */
let movingItemId = null;
let movingStartX, movingStartY;
let movingItemOrigX, movingItemOrigY;
let movingWrapper = null;

function onFieldMouseDown(e, itemId) {
    e.preventDefault();
    selectItem(itemId);

    movingItemId = itemId;
    movingStartX = e.clientX;
    movingStartY = e.clientY;
    const item = signItems.find(it => it._id === itemId);
    movingItemOrigX = item.posX;
    movingItemOrigY = item.posY;
    movingWrapper = pageWrappers[item.page].wrapper;
}

document.addEventListener('mousemove', e => {
    if (movingItemId === null) return;
    const rect = movingWrapper.getBoundingClientRect();
    const item = signItems.find(it => it._id === movingItemId);
    const dx = (e.clientX - movingStartX) / rect.width;
    const dy = (e.clientY - movingStartY) / rect.height;
    item.posX = Math.max(0, Math.min(1 - item.width,  movingItemOrigX + dx));
    item.posY = Math.max(0, Math.min(1 - item.height, movingItemOrigY + dy));
    item.posX = +item.posX.toFixed(4);
    item.posY = +item.posY.toFixed(4);
    const el = document.getElementById(`sfi-${movingItemId}`);
    if (el) {
        el.style.left = (item.posX * 100) + '%';
        el.style.top  = (item.posY * 100) + '%';
    }
    updatePosInfo(item);
    markDirty();
});

document.addEventListener('mouseup', () => {
    if (movingItemId !== null) {
        movingItemId = null;
        movingWrapper = null;
    }
});

/* ========================================================
   RESIZE
   ======================================================== */
let resizingItemId = null;
let resizingStartX, resizingStartY;
let resizingOrigW, resizingOrigH;
let resizingWrapper = null;

function onResizeStart(e, itemId) {
    e.preventDefault();
    e.stopPropagation();
    resizingItemId = itemId;
    resizingStartX = e.clientX;
    resizingStartY = e.clientY;
    const item = signItems.find(it => it._id === itemId);
    resizingOrigW = item.width;
    resizingOrigH = item.height;
    resizingWrapper = pageWrappers[item.page].wrapper;
}

document.addEventListener('mousemove', e => {
    if (resizingItemId === null) return;
    const rect = resizingWrapper.getBoundingClientRect();
    const item = signItems.find(it => it._id === resizingItemId);
    const dw = (e.clientX - resizingStartX) / rect.width;
    const dh = (e.clientY - resizingStartY) / rect.height;
    item.width  = Math.max(0.02, Math.min(1 - item.posX, resizingOrigW + dw));
    item.height = Math.max(0.01, Math.min(1 - item.posY, resizingOrigH + dh));
    item.width  = +item.width.toFixed(4);
    item.height = +item.height.toFixed(4);
    const el = document.getElementById(`sfi-${resizingItemId}`);
    if (el) {
        el.style.width  = (item.width  * 100) + '%';
        el.style.height = (item.height * 100) + '%';
    }
    updatePosInfo(item);
    markDirty();
});

document.addEventListener('mouseup', () => {
    if (resizingItemId !== null) {
        resizingItemId = null;
        resizingWrapper = null;
    }
});

/* ========================================================
   KEYBOARD DELETE
   ======================================================== */
document.addEventListener('keydown', e => {
    if ((e.key === 'Delete' || e.key === 'Backspace') &&
        selectedItemId !== null &&
        !['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)) {
        deleteItem(selectedItemId);
    }
    if (e.key === 'Escape') {
        deselectAll();
    }
});

/* ========================================================
   SELECT / DESELECT
   ======================================================== */
function selectItem(itemId) {
    // Deselect previous
    if (selectedItemId !== null) {
        const prev = document.getElementById(`sfi-${selectedItemId}`);
        if (prev) prev.classList.remove('selected');
    }
    selectedItemId = itemId;
    const el = document.getElementById(`sfi-${itemId}`);
    if (el) el.classList.add('selected');

    // Show properties panel
    const item = signItems.find(it => it._id === itemId);
    if (item) showPropsPanel(item);
}

function deselectAll() {
    if (selectedItemId !== null) {
        const prev = document.getElementById(`sfi-${selectedItemId}`);
        if (prev) prev.classList.remove('selected');
        selectedItemId = null;
    }
    hidePropsPanel();
}

// Click on viewer background → deselect
document.getElementById('es-viewer').addEventListener('mousedown', e => {
    if (e.target === document.getElementById('es-viewer') ||
        e.target.classList.contains('es-page-wrapper') ||
        e.target.tagName === 'CANVAS') {
        deselectAll();
    }
});

/* ========================================================
   PROPERTIES PANEL
   ======================================================== */
function showPropsPanel(item) {
    const meta = getTypeMeta(item.type);
    document.getElementById('es-props-title').textContent = meta.label + ' Field';
    document.getElementById('es-prop-name').value = item.name || '';
    document.getElementById('es-prop-placeholder').value = item.placeholder || '';
    document.getElementById('es-prop-required').checked = item.required !== false;

    const roleId = Array.isArray(item.responsible_id) ? item.responsible_id[0] : (item.responsible_id || '');
    document.getElementById('es-prop-role').value = roleId || '';

    updatePosInfo(item);

    document.getElementById('es-field-palette').style.display = 'none';
    document.getElementById('es-props-panel').classList.add('visible');
}

function hidePropsPanel() {
    document.getElementById('es-props-panel').classList.remove('visible');
    document.getElementById('es-field-palette').style.display = '';
}

function updatePosInfo(item) {
    document.getElementById('pi-x').textContent = (item.posX * 100).toFixed(1) + '%';
    document.getElementById('pi-y').textContent = (item.posY * 100).toFixed(1) + '%';
    document.getElementById('pi-w').textContent = (item.width  * 100).toFixed(1) + '%';
    document.getElementById('pi-h').textContent = (item.height * 100).toFixed(1) + '%';
}

// Properties changes → update item
function syncPropsToItem() {
    if (selectedItemId === null) return;
    const item = signItems.find(it => it._id === selectedItemId);
    if (!item) return;
    item.name = document.getElementById('es-prop-name').value;
    item.placeholder = document.getElementById('es-prop-placeholder').value;
    item.required = document.getElementById('es-prop-required').checked;
    const roleVal = document.getElementById('es-prop-role').value;
    item.responsible_id = roleVal ? parseInt(roleVal) : false;

    // Update the overlay label
    const el = document.getElementById(`sfi-${selectedItemId}`);
    if (el) {
        const lbl = el.querySelector('.sign-field-label');
        if (lbl) lbl.textContent = item.name || getTypeMeta(item.type).icon;
        // Update role color
        applyRoleColorToEl(el, item.responsible_id);
    }
    markDirty();
    updatePlacedList();
}

document.getElementById('es-prop-name').addEventListener('input', syncPropsToItem);
document.getElementById('es-prop-placeholder').addEventListener('input', syncPropsToItem);
document.getElementById('es-prop-required').addEventListener('change', syncPropsToItem);
document.getElementById('es-prop-role').addEventListener('change', syncPropsToItem);

document.getElementById('es-props-close').addEventListener('click', deselectAll);

document.getElementById('es-props-delete').addEventListener('click', () => {
    if (selectedItemId !== null) deleteItem(selectedItemId);
});

/* ========================================================
   DELETE ITEM
   ======================================================== */
function deleteItem(itemId) {
    // Remove DOM element
    const el = document.getElementById(`sfi-${itemId}`);
    if (el) el.remove();

    // Remove from state
    const idx = signItems.findIndex(it => it._id === itemId);
    if (idx !== -1) signItems.splice(idx, 1);

    if (selectedItemId === itemId) {
        selectedItemId = null;
        hidePropsPanel();
    }

    // Show empty hint if no more fields on that page
    Object.keys(pageWrappers).forEach(pg => {
        const pgNum = parseInt(pg);
        const hasFields = signItems.some(it => it.page === pgNum);
        const hint = document.getElementById(`page-hint-${pgNum}`);
        if (hint) hint.style.display = hasFields ? 'none' : '';
    });

    markDirty();
    updatePlacedList();
}

/* ========================================================
   PLACED FIELDS LIST
   ======================================================== */
function updatePlacedList() {
    const list = document.getElementById('es-placed-list');
    const empty = document.getElementById('es-placed-empty');
    const badge = document.getElementById('es-field-count-badge');

    badge.textContent = signItems.length;

    if (signItems.length === 0) {
        empty.style.display = '';
        // Remove all row items
        list.querySelectorAll('.es-placed-row').forEach(r => r.remove());
        return;
    }
    empty.style.display = 'none';
    list.querySelectorAll('.es-placed-row').forEach(r => r.remove());

    signItems.forEach(item => {
        const meta = getTypeMeta(item.type);
        const row = document.createElement('div');
        row.className = 'es-placed-row';
        row.style.cssText = `
            display:flex; align-items:center; gap:8px; padding:7px 8px;
            border-radius:8px; cursor:pointer;
            background: rgba(255,255,255,0.03);
            border:1px solid transparent;
            transition:all 0.15s; margin-bottom:3px;
        `;
        row.innerHTML = `
            <div style="width:24px;height:24px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:13px;background:rgba(255,255,255,0.07);">${meta.icon}</div>
            <div style="flex:1;min-width:0;">
                <div style="font-size:12px;font-weight:600;color:#cbd5e1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${item.name || meta.label}</div>
                <div style="font-size:10px;color:#475569;">Page ${item.page}</div>
            </div>
        `;
        row.addEventListener('click', () => {
            selectItem(item._id);
            // Scroll to it
            const el = document.getElementById(`sfi-${item._id}`);
            if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        });
        list.appendChild(row);
    });
}

/* ========================================================
   DIRTY / STATUS
   ======================================================== */
function markDirty() {
    isDirty = true;
    const status = document.getElementById('es-save-status');
    const txt = document.getElementById('es-save-text');
    status.className = 'es-save-status';
    txt.textContent = 'Unsaved changes';
}

function markSaved() {
    isDirty = false;
    const status = document.getElementById('es-save-status');
    const txt = document.getElementById('es-save-text');
    status.className = 'es-save-status saved';
    txt.textContent = 'All changes saved';
}

/* ========================================================
   SAVE
   ======================================================== */
async function saveTemplate() {
    const btn = document.getElementById('es-btn-save');
    btn.disabled = true;
    btn.textContent = '⏳ Saving…';

    const status = document.getElementById('es-save-status');
    const txt = document.getElementById('es-save-text');
    status.className = 'es-save-status saving';
    txt.textContent = 'Saving…';

    // Build payload
    const payload = signItems.map(item => {
        const typeId = Array.isArray(item.type_id) ? item.type_id[0] : item.type_id;
        const roleId = Array.isArray(item.responsible_id) ? item.responsible_id[0] : (item.responsible_id || false);
        return {
            id: item.id > 0 ? item.id : 0,
            type_id: typeId,
            page: item.page,
            posX: item.posX,
            posY: item.posY,
            width: item.width,
            height: item.height,
            required: item.required,
            responsible_id: roleId || false,
            name: item.name || '',
            placeholder: item.placeholder || '',
            alignment: 'center',
        };
    });

    try {
        const response = await fetch('/sign/template/' + TEMPLATE_ID + '/save', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { items: payload } }),
        });
        const result = await response.json();
        if (result.result === true || result.result) {
            markSaved();
            showToast('✓ Template saved successfully!', 'success');
            // Reload to get real IDs for newly created items
            setTimeout(() => location.reload(), 1200);
        } else {
            throw new Error(result.error?.data?.message || 'Save failed');
        }
    } catch (err) {
        status.className = 'es-save-status error';
        txt.textContent = 'Save failed';
        showToast('✗ ' + (err.message || 'Failed to save'), 'error');
    } finally {
        btn.disabled = false;
        btn.innerHTML = '&#10003; Save Template';
    }
}

window.saveTemplate = saveTemplate;

/* ========================================================
   DISCARD
   ======================================================== */
function discardChanges() {
    if (isDirty) {
        if (!confirm('Discard all unsaved changes?')) return;
    }
    location.reload();
}
window.discardChanges = discardChanges;

/* ========================================================
   TOAST
   ======================================================== */
function showToast(msg, type = 'success') {
    const toast = document.getElementById('es-toast');
    toast.textContent = msg;
    toast.className = `es-toast ${type} show`;
    setTimeout(() => { toast.classList.remove('show'); }, 3000);
}

/* ========================================================
   BOOT
   ======================================================== */
// Populate sign items from server
function parseSignItems(raw) {
    return raw.map(it => ({
        _id: it.id, // real DB id as _id for existing items
        id: it.id,
        type_id: it.type_id,
        type: it.type_id ? it.type_id[1] : 'text', // [id, item_type] pair? Let's resolve below
        page: it.page,
        posX: it.posX,
        posY: it.posY,
        width: it.width,
        height: it.height,
        required: it.required,
        responsible_id: it.responsible_id,
        name: it.name || '',
        placeholder: it.placeholder || '',
    }));
}

// Resolve item_type string from type_id
function resolveItemType(item) {
    if (!item.type_id) return 'text';
    const typeIdNum = Array.isArray(item.type_id) ? item.type_id[0] : item.type_id;
    const found = SIGN_ITEM_TYPES.find(t => t.id === typeIdNum);
    return found ? found.item_type : 'text';
}

// Initialize
signItems = INITIAL_ITEMS.map(it => {
    const obj = {
        _id: it.id,
        id: it.id,
        type_id: it.type_id,
        type: resolveItemType(it),
        page: it.page,
        posX: it.posX,
        posY: it.posY,
        width: it.width,
        height: it.height,
        required: it.required,
        responsible_id: it.responsible_id,
        name: it.name || '',
        placeholder: it.placeholder || '',
    };
    return obj;
});

buildFieldCards();
buildRoleSelect();
renderPDF('/sign/template/' + TEMPLATE_ID + '/pdf');

// Mark as saved initially (no unsaved changes)
const statusEl = document.getElementById('es-save-status');
const statusTxt = document.getElementById('es-save-text');
statusEl.className = 'es-save-status saved';
statusTxt.textContent = 'No unsaved changes';

})();
